CREATE TABLE `asegurados` (`id_asegurado` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(110) NOT NULL COMMENT 'Nombre completo', `correo` VARCHAR(160) NOT NULL, `ciudad` VARCHAR(90), `fecha_registro` DATE NOT NULL, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_asegurado`)) ENGINE=InnoDB COMMENT='Personas registradas';
CREATE TABLE `familias_poliza` (`id_familia_poliza` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(100) NOT NULL, `descripcion` VARCHAR(180), PRIMARY KEY (`id_familia_poliza`)) ENGINE=InnoDB COMMENT='Clasificación de recursos';
CREATE TABLE `planes_seguro` (`id_plan_seguro` INT NOT NULL AUTO_INCREMENT, `id_familia_poliza` INT NOT NULL, `nombre` VARCHAR(130) NOT NULL, `prima` DECIMAL(11,2) NOT NULL, `capacidad` INT NOT NULL DEFAULT 0, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_plan_seguro`), KEY `idx_recurso_categoria` (`id_familia_poliza`), CONSTRAINT `fk_recurso_categoria` FOREIGN KEY (`id_familia_poliza`) REFERENCES `familias_poliza` (`id_familia_poliza`)) ENGINE=InnoDB COMMENT='Recursos o artículos del catálogo';
CREATE TABLE `oficinas` (`id_oficina` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(110) NOT NULL, `ciudad` VARCHAR(90) NOT NULL, `fecha_apertura` DATE, PRIMARY KEY (`id_oficina`)) ENGINE=InnoDB COMMENT='Ubicaciones operativas';
CREATE TABLE `agentes` (`id_agente` INT NOT NULL AUTO_INCREMENT, `id_oficina` INT NOT NULL, `nombre` VARCHAR(110) NOT NULL, `salario` DECIMAL(11,2), `fecha_ingreso` DATE, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_agente`), KEY `idx_empleado_sede` (`id_oficina`), CONSTRAINT `fk_empleado_sede` FOREIGN KEY (`id_oficina`) REFERENCES `oficinas` (`id_oficina`)) ENGINE=InnoDB COMMENT='Personal';
CREATE TABLE `contratos` (`id_contrato` INT NOT NULL AUTO_INCREMENT, `id_asegurado` INT NOT NULL, `id_agente` INT NOT NULL, `id_oficina` INT NOT NULL, `fecha` DATE NOT NULL, `estado` VARCHAR(25) NOT NULL, `total` DECIMAL(12,2) NOT NULL, `comentario` VARCHAR(180), PRIMARY KEY (`id_contrato`), KEY `idx_operacion_persona` (`id_asegurado`), KEY `idx_operacion_empleado` (`id_agente`), KEY `idx_operacion_sede` (`id_oficina`), CONSTRAINT `fk_operacion_persona` FOREIGN KEY (`id_asegurado`) REFERENCES `asegurados` (`id_asegurado`), CONSTRAINT `fk_operacion_empleado` FOREIGN KEY (`id_agente`) REFERENCES `agentes` (`id_agente`), CONSTRAINT `fk_operacion_sede` FOREIGN KEY (`id_oficina`) REFERENCES `oficinas` (`id_oficina`)) ENGINE=InnoDB COMMENT='Registro principal de operaciones';
CREATE TABLE `coberturas_contratadas` (`id_cobertura_contratada` INT NOT NULL AUTO_INCREMENT, `id_contrato` INT NOT NULL, `id_plan_seguro` INT NOT NULL, `cantidad` INT NOT NULL, `precio_unitario` DECIMAL(11,2) NOT NULL, `descuento` DECIMAL(10,2) NOT NULL DEFAULT 0, PRIMARY KEY (`id_cobertura_contratada`), KEY `idx_detalle_operacion` (`id_contrato`), KEY `idx_detalle_recurso` (`id_plan_seguro`), CONSTRAINT `fk_detalle_operacion` FOREIGN KEY (`id_contrato`) REFERENCES `contratos` (`id_contrato`), CONSTRAINT `fk_detalle_recurso` FOREIGN KEY (`id_plan_seguro`) REFERENCES `planes_seguro` (`id_plan_seguro`)) ENGINE=InnoDB COMMENT='Detalle de recursos por operación';
CREATE TABLE `pagos_prima` (`id_pago_prima` INT NOT NULL AUTO_INCREMENT, `id_contrato` INT NOT NULL, `fecha_pago` DATE NOT NULL, `monto` DECIMAL(12,2) NOT NULL, `metodo` VARCHAR(25) NOT NULL, `confirmado` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_pago_prima`), KEY `idx_pago_operacion` (`id_contrato`), CONSTRAINT `fk_pago_operacion` FOREIGN KEY (`id_contrato`) REFERENCES `contratos` (`id_contrato`)) ENGINE=InnoDB COMMENT='Movimientos de cobro';
CREATE TABLE `siniestros` (`id_siniestro` INT NOT NULL AUTO_INCREMENT, `id_contrato` INT NOT NULL, `fecha_evento` DATE NOT NULL, `tipo` VARCHAR(50) NOT NULL, `descripcion` VARCHAR(220), `puntuacion` INT, PRIMARY KEY (`id_siniestro`), KEY `idx_evento_operacion` (`id_contrato`), CONSTRAINT `fk_evento_operacion` FOREIGN KEY (`id_contrato`) REFERENCES `contratos` (`id_contrato`)) ENGINE=InnoDB COMMENT='Eventos de seguimiento asociados a una operación';
